  {"message_id": "msg_1001", "thread_id": "thread_1001", "subject": "Re: XinYuan Group Q2 Service Planning", "from": "zhangming@xinyuan.com", "to": "sales@company.com", "date": "2026-03-25T09:00:00Z", "body": "Hi Lisa, the Q1 system upgrade worked great -- our efficiency improved by 30%. For Q2, we'd like to discuss expanding to the supply chain module, with a budget of about 1 million yuan. Also, we have no issues with the renewal terms and can sign next week.", "is_read": true},
